// Example of a common memory leak: Forgotten Timers
function startLeaking() {
  const massiveData = new Array(1000000).fill('leak');

  // This interval runs forever, keeping massiveData in memory
  // because the closure references it!
  setInterval(() => {
    console.log('Still tracking massive data length:', massiveData.length);
  }, 1000);
}

// Correct approach: Clean up intervals
function runSafely() {
  const temp = "safe data";
  const intervalId = setInterval(() => console.log(temp), 1000);

  // Clear it when done
  setTimeout(() => clearInterval(intervalId), 5000);
}
